fn identifier(value: &str) -> bool {
    !value.is_empty() && value.len() <= 256 && value.bytes().all(|b| b.is_ascii_graphic())
}

/// Canonical HTTPS DNS origin (optional nondefault decimal port). The operator
/// helper uses the same restricted shape; unsupported IPv6 fails closed.
